mapper.select:
SELECT c.roomIdx FROM chatRoom c
JOIN chatMember m1 ON c.roomIdx = m1.roomIdx AND m1.userIdx = #{buyerIdx}
JOIN chatMember m2 ON c.roomIdx = m2.roomIdx AND m2.userIdx = #{sellerIdx}
WHERE c.tradeIdx = #{tradeIdx}

SELECT u.nickname FROM chatMember m
JOIN users u ON m.userIdx = u.USERIDX
WHERE m.roomIdx = #{roomIdx} AND m.userIdx != #{myUserIdx}

SELECT c.roomIdx FROM chatRoom c
JOIN chatMember m1 ON c.roomIdx = m1.roomIdx AND m1.userIdx = #{buyerIdx}
JOIN chatMember m2 ON c.roomIdx = m2.roomIdx AND m2.userIdx = #{sellerIdx}
WHERE c.tradeIdx = #{albaIdx} AND c.roomType = 3
